Let $\mathbf{X}$, $\mathbf{Y}$, $\mathbf{Z}$, and $\mathbf{W}$ be pairwise disjoint node sets in a causal MPDAG $\mathcal{G}=(\mathbf{V,E})$. Let $\mathcal{G}_{\overline{\mathbf{X}}\underline{\mathbf{Z}}}$ denote the graph obtained by deleting all edges into $\mathbf{X}$ and all edges out of $\mathbf{Z}$ from $\mathcal{G}$. We write $\mathcal{G}_{\overline{\mathbf{X}}\underline{\mathbf{Z}}}$ as $\mathcal{G}_{\underline{\mathbf{Z}}}$ when $\mathbf{X}$ is empty and as $\mathcal{G}_{\overline{\mathbf{X}}}$ when $\mathbf{Z}$ is empty. Then the following hold for all densities $f$ consistent with $\mathcal{G}$.
    \vskip .075in

    \textbf{Rule~1.} If $(\mathbf{Y} \perp_{d} \mathbf{Z} | \mathbf{X}, \mathbf{W})_{\mathcal{G}_{\overline{\mathbf{X}}}}$, then
    \begin{align}
        f(\mathbf{y} | do(\mathbf{x}), \mathbf{z}, \mathbf{w}) = f(\mathbf{y} | do(\mathbf{x}), \mathbf{w}). 
    \end{align}

    \textbf{Rule~2.} If $(\mathbf{Y} \perp_{d} \mathbf{Z} | \mathbf{X}, \mathbf{W})_{\mathcal{G}_{\overline{\mathbf{X}}\underline{\mathbf{Z}}}}$, then
    \begin{align} 
        f(\mathbf{y} | do(\mathbf{z}), \mathbf{w}, do(\mathbf{x})) = f(\mathbf{y} | \mathbf{z}, \mathbf{w}, do(\mathbf{x})).
    \end{align}

    \textbf{Rule~3.} If $(\mathbf{Y} \perp_{d} \mathbf{Z} | \mathbf{X}, \mathbf{W})_{\mathcal{G}_{\overline{\mathbf{X}}, \overline{\mathbf{Z'(W)}}}}$, then
    \begin{align}

        \begin{split}
            f(\mathbf{y} | do(\mathbf{z}), \mathbf{w}, do(\mathbf{x})) = f(\mathbf{y} | \mathbf{w}, do(\mathbf{x})),
        \end{split}
    \end{align}
    \hskip .86in where $\mathbf{Z'(W)} := \mathbf{Z} \setminus \mathrm{PossAn}(\mathbf{W}, \mathcal{G}_{\mathbf{V} \setminus \mathbf{X}})$.
